) {
    var showDialog by remember { mutableStateOf(false) } // dialog state

    if (showDialog) {
        EditItemDialog(
            item,
            onConfirm = { updatedItem ->
                // update the item, and submit changes to Firestore or other actions
                // ...

                showDialog = false
            },
            onCancel = {
                showDialog = false
            }
        )
    }

    Row(
        modifier = Modifier
            .fillMaxWidth(0.8f)
            .height(75.dp)
            .clip(RoundedCornerShape(16.dp))
            .background(MaterialTheme.colorScheme.primary)
            .clickable(onClick = { showDialog = true }), // show the dialog when the card is clicked
        verticalAlignment = Alignment.CenterVertically
    ) {
        // ... your existing code ...
    }
}

@Composable
fun EditItemDialog(
    item: InventoryItem,
    onConfirm: (InventoryItem) -> Unit,
    onCancel: () -> Unit
) {
    // maintain state for editable fields
    var stock by remember { mutableStateOf(item.stock) }
    var price by remember { mutableStateOf(item.price ?: 0.0) }

    AlertDialog(
        onDismissRequest = onCancel,
        title = { Text(text = "Edit Item") },
        text = {
            Column {
                TextField(
                    value = stock.toString(),
                    onValueChange = { newText ->
                        stock = newText.toIntOrNull() ?: item.stock
                    },
                    label = { Text("Stock") },
                    keyboardType = KeyboardType.Number
                )
                TextField(
                    value = price.toString(),
                    onValueChange = { newText ->
                        price = newText.toDoubleOrNull() ?: item.price ?: 0.0
                    },
                    label = { Text("Price") },
                    keyboardType = KeyboardType.Number
                )
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val updatedItem = item.copy(
                        stock = stock,
                        price = price
                    )
                    onConfirm(updatedItem)
                }
            ) {
                Text("Confirm")
            }
        },
        dismissButton = {
            Button(onClick = onCancel) {
                Text("Cancel")
            }
        }
    )
}
