```
use warp::{Filter, http::header};

// Define a middleware function to add a custom header to the response
fn custom_header() -> impl Filter<Extract = (), Error = warp::Rejection> + Clone {
    warp::header::exact("Custom-Header", "Hello, World!")
        .map(|_| ())
}

// Define a handler function to handle the request
async fn hello() -> &'static str {
    "Hello, World!"
}

#[tokio::main]
