Java-code in MainActivity:

```
public class MainActivity extends AppCompatActivity implements OnMapReadyCallback, GoogleApiClient.ConnectionCallbacks,
        GoogleApiClient.OnConnectionFailedListener, LocationListener, ResultCallback<Status> {

    private GoogleMap mMap;
    private GoogleApiClient mGoogleApiClient;
    private LocationRequest mLocationRequest;
    private Location mLastLocation;
    private boolean mFenceEntered;
    private GeofenceHelper mGeofenceHelper;
    private GeofencingClient mGeofencingClient;
    private SimpleGeofence mGeofence;
    private PendingIntent mGeofencePendingIntent;
    private Button mBtnAddGeofence;
    private TextView mTextView;

    private static final long GEOFENCE_EXPIRATION_TIME = 60 * 60 * 1000;
    private static final int MY_PERMISSIONS_REQUEST_LOCATION = 99;
    private static final int GEOFENCE_RADIUS_IN_METERS = 100;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        mTextView = findViewById(R.id.textView);
        mBtnAddGeofence = findViewById(R.id.btnAddGeofence);

        mGeofenceHelper = new GeofenceHelper(this);
        mGeofencingClient = LocationServices.getGeofencingClient(this);

        checkLocationPermission();

        mBtnAddGeofence.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                if (mMap != null) {
                    addGeofence();
                }
            }
        });

        SupportMapFragment mapFragment = (SupportMapFragment) getSupportFragmentManager()
                .findFragmentById(R.id.map);
        mapFragment.getMapAsync(this);
    }

    private void addGeofence() {
        LatLng latLng = new LatLng(mLastLocation.getLatitude(), mLastLocation.getLongitude());
        mGeofence = new SimpleGeofence("my_geofence", latLng.latitude, latLng.longitude, GEOFENCE_RADIUS_IN_METERS, GEOFENCE_EXPIRATION_TIME, Geofence.GEOFENCE_TRANSITION_ENTER);
        mGeofencingClient.addGeofences(getGeofencingRequest(), getGeofencePendingIntent()).addOnCompleteListener(this);
    }

    private GeofencingRequest getGeofencingRequest() {
        GeofencingRequest.Builder builder = new GeofencingRequest.Builder();
        builder.setInitialTrigger(GeofencingRequest.INITIAL_TRIGGER_ENTER);
        builder.addGeofence(mGeofence.toGeofence());
        return builder.build();
    }

    private PendingIntent getGeofencePendingIntent() {
        if (mGeofencePendingIntent != null) {
            return mGeofencePendingIntent;
        }

        Intent intent = new Intent(this, GeofenceService.class);
        mGeofencePendingIntent = PendingIntent.getService(this, 0, intent, PendingIntent.FLAG_UPDATE_CURRENT);
        return mGeofencePendingIntent;
    }

    @Override
    protected void onStart() {
        super.onStart();
        mGoogleApiClient.connect();
    }

    @Override
    protected void onStop() {
        super.onStop();
        mGoogleApiClient.disconnect();
    }

    @Override
    public void onConnected(@Nullable Bundle bundle) {
        startLocationUpdates();
    }

    @Override
    public void onConnectionSuspended(int i) {
        mGoogleApiClient.connect();
    }

    @Override
    public void onConnectionFailed(@NonNull ConnectionResult connectionResult) {
    }

    @Override
    public void onLocationChanged(Location location) {
        mLastLocation = location;
        LatLng latLng = new LatLng(location.getLatitude(), location.getLongitude());
        mMap.moveCamera(CameraUpdateFactory.newLatLng(latLng));
        mMap.animateCamera(CameraUpdateFactory.zoomTo(15));
    }

    protected synchronized void buildGoogleApiClient() {
        mGoogleApiClient = new GoogleApiClient.Builder(this)
                .addConnectionCallbacks(this)
                .addOnConnectionFailedListener(this)
                .addApi(LocationServices.API)
                .build();

        mLocationRequest = new LocationRequest();
        mLocationRequest.setInterval(1000);
        mLocationRequest.setFastestInterval(1000);
        mLocationRequest.setPriority(LocationRequest.PRIORITY_HIGH_ACCURACY);
    }

    private void startLocationUpdates() {
        if (ActivityCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED) {
            LocationServices.FusedLocationApi.requestLocationUpdates(mGoogleApiClient, mLocationRequest, this);
        }
    }

    @Override
    public void onResult(@NonNull Status status) {
        if (status.isSuccess()) {
            Log.d("Geofencing", "Success");
        } else {
            Log.d("Geofencing", "Error: " + status.getStatusMessage());
        }
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, @NonNull String permissions[], @NonNull int[] grantResults) {
        switch (requestCode) {
            case MY_PERMISSIONS_REQUEST_LOCATION: {
                if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                    if (ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED) {
                        mGoogleApiClient = new GoogleApiClient.Builder(this)
                                .addConnectionCallbacks(this)
                                .addOnConnectionFailedListener(this)
                                .addApi(LocationServices.API)
                                .build();
                        mGoogleApiClient.connect();
                        mMap.setMyLocationEnabled(true);
                    }
                } else {
                    Toast.makeText(this, "permission denied", Toast.LENGTH_LONG).show();
                }
                return;
            }
        }
    }

    private void checkLocationPermission() {
        if (ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION) != PackageManager.PERMISSION_GRANTED) {
            ActivityCompat.requestPermissions(this, new String[]{Manifest.permission.ACCESS_FINE_LOCATION}, MY_PERMISSIONS_REQUEST_LOCATION);
        }
    }

    @Override
    public void onMapReady(GoogleMap googleMap) {
        mMap = googleMap;
        mMap.setMapType(GoogleMap.MAP_TYPE_NORMAL);
        mMap.getUiSettings().setZoomControlsEnabled(true);
        mMap.getUiSettings().setCompassEnabled(true);

        buildGoogleApiClient();
    }

    public class GeofenceHelper {

        private final String TAG = GeofenceHelper.class.getSimpleName();
        private Context mContext;

        public GeofenceHelper(Context context) {
            mContext = context;
        }

        public GeofencingRequest getGeofencingRequest(Geofence geofence) {
            GeofencingRequest.Builder builder = new GeofencingRequest.Builder();
            builder.setInitialTrigger(GeofencingRequest.INITIAL_TRIGGER_ENTER);
            builder.addGeofence(geofence);
            return builder.build();
        }

        public Geofence getGeofence(String geofenceId, double lat, double lon, float radius, int transitionType) {
            return new Geofence.Builder()
                    .setRequestId(geofenceId)
                    .setCircularRegion(lat, lon, radius)
                    .setTransitionTypes(transitionType)
                    .setExpirationDuration(Geofence.NEVER_EXPIRE)
                    .build();
        }
    }

    public class SimpleGeofence {

        private String geofenceId;
        private double latitude;
        private double longitude;
        private float radius;
        private long expirationDuration;
        private int transitionType;

        public SimpleGeofence(String geofenceId, double latitude, double longitude, float radius, long expiration, int transition) {
            this.geofenceId = geofenceId;
            this.latitude = latitude;
            this.longitude = longitude;
            this.radius = radius;
            this.expirationDuration = expiration;
            this.transitionType = transition;
        }

        public Geofence toGeofence() {
            return new Geofence.Builder()
                    .setRequestId(geofenceId)
                    .setCircularRegion(latitude, longitude, radius)
                    .setExpirationDuration(expirationDuration)
                    .setTransitionTypes(transitionType)
                    .build();
        }
    }
}
```

Java-code in GeofenceService:

```
public class GeofenceService extends IntentService {

    private NotificationManager mNotificationManager;
    private static final int NOTIFICATION_ID = 1;

    public GeofenceService() {
        super("GeofenceService");
    }

    @Override
    public void onHandleIntent(Intent intent) {
        GeofencingEvent geofencingEvent = GeofencingEvent.fromIntent(intent);
        if (geofencingEvent.hasError()) {
            Log.e("GeofenceService", "GeofencingEvent Error: " + geofencingEvent.getErrorCode());
            return;
        }

        int geofenceTransition = geofencingEvent.getGeofenceTransition();
        if (geofenceTransition == Geofence.GEOFENCE_TRANSITION_ENTER) {
            showNotification("Entered Geofence");
        } else if (geofenceTransition == Geofence.GEOFENCE_TRANSITION_EXIT) {
            showNotification("Exited Geofence");
        }
    }

    private void showNotification(String message) {
        mNotificationManager = (NotificationManager) this.getSystemService(Context.NOTIFICATION_SERVICE);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            createChannel();
        }

        PendingIntent contentIntent = PendingIntent.getActivity(this, 0, new Intent(this, MainActivity.class), PendingIntent.FLAG_UPDATE_CURRENT);

        NotificationCompat.Builder notificationBuilder = new NotificationCompat.Builder(this, "channel_geofence")
                .setContentTitle("Geofence Alert")
                .setContentText(message)
                .setPriority(Notification.PRIORITY_HIGH)
                .setAutoCancel(true)
                .setSmallIcon(R.mipmap.ic_launcher)
                .setContentIntent(contentIntent);

        mNotificationManager.notify(NOTIFICATION_ID, notificationBuilder.build());
    }

    private void createChannel() {
        NotificationChannel channel = new NotificationChannel("channel_geofence", "Geofence", NotificationManager.IMPORTANCE_DEFAULT);
        channel.setDescription("Geofence channel");
        mNotificationManager.createNotificationChannel(channel);
    }
}
```

In this code, we request for user's location permissions, connect to the GoogleApiClient to get current location updates, and add a geofence with a radius of 100 meters around the current location. When the geofence is entered or exited by the user or any device (in case of Shared Geofences), it sends a broadcast which is received by GeofenceService where a notification is shown. Note that we've subclassed IntentService, it obtains the location of the geofence transition from the Intent's extras, determines the transition type with getTransitionType(), and sends a notification to the user with displayNotification()."},
