Let's modify the `initUserExpenses` function to update the stock map field for the given `name`, incrementing the stock value by `inventoryStockChange`. In this example, I'll assume your inventory document has a field called `stockMap` which is a map with the item name as the key and the stock value as the value.

```kotlin
fun initUserExpenses(
    name: String,
    quantity: Int,
    expense: Double,
    collectionName: String,
    documentId: String,
    inventoryStockChange: Int,
    inventoryDocumentId: String,
    firestore: FirebaseFirestore
) {
    val db = FirebaseFirestore.getInstance()
    val docRef = db
        .collection("expenses")
        .document("Kantin")
        .collection(collectionName)
        .document(documentId)

    docRef.get()
        .addOnSuccessListener { document ->

            // ...Rest of the code

            val stockRef = db
                .collection("inventory")
                .document(inventoryDocumentId)

            // ...Rest of the code

            firestore.runTransaction { transaction ->
                if (document.exists()) {
                    transaction.update(docRef, updateData)
                    transaction.update(docRef, "total", FieldValue.increment(expense))
                } else {
                    transaction.set(docRef, updateData + mapOf("total" to expense))
                }

                // Update the stock map in the inventory document
                val stockFieldName = "stockMap.$name" // Compose the field name using dot notation
                transaction.update(stockRef, stockFieldName, FieldValue.increment(inventoryStockChange.toLong()))
            }.addOnSuccessListener {
                Log.d("TAG", "Berhasil")
            }.addOnFailureListener { exception ->
                Log.e("TAG", "Gagal", exception)
            }
