class Thing {
  constructor(name) {
    this.name = name;
    this.is_a = {};
    this.is_not_a = {};
    this.has = (num) => {
      this.currentThingCount = num;
      this.currentThingArr = [];
      return this;
    };
    this.having = (num) => {
      return this.has(num);
    };
    this.each = (callback) => {
      for(let i = 0; i < this.currentThingCount; i++) {
        const thing = new Thing(this.currentThingName);
        this.currentThingArr.push(thing);
        callback(thing);
      }
      return this;
    };
    this.being_the = (attrValue) => {
      this.currentThingArr.forEach(thing => {
        thing[attrValue.attr] = attrValue.value;
      });
      return this;
    };
    this.and_the = (attrValue) => {
      return this.being_the(attrValue);
    };
    this.is_the = (value) => {
      this[value.attr] = value.value;
      return this;
    };
    this.can = (methodName, callback) => {
      if(typeof methodName === 'function') {
        this[methodName.name] = methodName.bind(this);
      } else {
        this[methodName] = callback.bind(this);
        this[methodName + 'Results'] = [];
      }
      return this;
    };
    this.has(1);
  }
  get is_a_woman() {
    return this.is_a.woman ? true : false;
  }
  get is_a_man() {
    return this.is_a.man ? true : false;
  }
  is_not_a_a(attr) {
    const isNotA = `is_not_a_${attr}`;
    return this[isNotA] ? true : false;
  }
  is_a_a(attr) {
    const isA = `is_a_${attr}`;
    return this[isA] ? true : false;
  }
  set is_a(targets) {
    if(typeof targets === 'object' && targets !== null) {
      for(let target in targets) {
        this[`is_a_${target}`] = targets[target];
      }
    }
  }
  set is_not_a(targets) {
    if(typeof targets === 'object' && targets !== null) {
      for(let target in targets) {
        this[`is_not_a_${target}`] = targets[target];
      }
    }
  }
}"},
