                        WidgetPackets.widgetAction(item, "Withdraw-1")
                        MousePackets.queueClickPacket(0, 0)
                        ItemPackets.queueItemAction1Packet(
                            WidgetInfo.BANK_INVENTORY_ITEMS_CONTAINER.packedId,
                            item.itemId,
                            firstFree
                        )
