{"role": "assistant", "content": "👽: Sure, here is the Java code equivalent of the Kotlin code you provided:

@PluginDescriptor(
    name = "Bank Setups",
    description = "Allows saving and loading bank setups. Hold shift to remove setups. Not yet working with noted items :("
)
public class BankSetups extends Plugin {
    private Configuration<BankSetupConfig> config = configuration(BankSetupConfig.class);
    private Overlay overlay = overlay(new BankSetupsOverlay());
    private int state = -1;
    private ItemManager itemManager;
    private List<BankSetupObject> bankSetups = new ArrayList<BankSetupObject>();
    private int wait = 0;
    private int dialogClose = 0;

    @Override
    public void onStart() {
        state = -1;
        if (!FileUtil.exists(this, "bankSetups.json")) {
            FileUtil.writeJson(this, "bankSetups.json", bankSetups);
        } else {
            bankSetups = FileUtil.readJson(this, "bankSetups.json", new TypeToken<List<BankSetupObject>>() {});
        }
    }

    @Override
    public void onStop() {
        state = -1;
    }

    @Override
    public void onMenuOptionClicked(MenuOptionClicked event) {
        String option = event.getMenuOption();

        if (option.contains("save-current")) {
            event.consume();
            List<int[]> invent = invent();
            List<int[]> equipment = equipment();
            nameInput(invent, equipment);
        } else if (option.contains("<col=00FFFF>Inventory:</col>")) {
            event.consume();
            bankSetups.set(0, bankSetups.get(event.getId()));
            state = 1;
        } else if (option.contains("<col=00FFFF>Remove:</col>")) {
            event.consume();
            bankSetups.remove(event.getId());
            FileUtil.writeJson(this, "bankSetups.json", bankSetups);
        }
    }

    private void nameInput(List<int[]> invent, List<int[]> equipment) {
        bankSetups.add(new BankSetupObject(config.setupName(), invent, equipment));
        FileUtil.writeJson(this, "bankSetups.json", bankSetups);
    }

    public void onClientTick(ClientTick event) {
        if (wait > 0) {
            if (Dialog.isEnterInputOpen()) {
                GameThread.invoke(() -> client.runScript(138));
            }
        }

        int firstFree = Inventory.getFreeSlots();
        switch (state) {
            case 1:
                if (Equipment.getAll() != null) {
                    Bank.depositEquipment();
                }
                if (Inventory.getAll() != null) {
                    Bank.depositInventory();
                }
                state = 2;
                break;
            case 2:
                if (Equipment.getAll() == null && Inventory.getAll() == null) {
                    for (int[] it : bankSetups.get(0).equipment) {
                        Item item = Bank.Inventory.getAll(it[0]);
                        if (item == null) {
                            int y = itemManager.canonicalize(it[0]);
                            item = getBankItemWidget(y);
                            if (item == null) {
                                continue;
                            }
                        }

                        if (it[1] != 1) {
                            WidgetPackets.widgetAction(item, "Withdraw-X");
                            DialogPackets.sendNumberInput(it[1]);
                            MousePackets.queueClickPacket(0, 0);
                            ItemPackets.queueItemAction1Packet(WidgetInfo.BANK_INVENTORY_ITEMS_CONTAINER.getPackedId(), item, firstFree);
                            return;
                        }

                        WidgetPackets.widgetAction(item, "Withdraw-1");
                        MousePackets.queueClickPacket(0, 0);
                        ItemPackets.queueItemAction1Packet(WidgetInfo.BANK_INVENTORY_ITEMS_CONTAINER.getPackedId(), item.getId(), firstFree);
                        state = 3;
                    }
                }
                break;
            case 3:
                for (int[] it : bankSetups.get(0).equipment) {
                    Item items[] = Items.getFirst(it);
                    if (items == null) {
                        continue;
                    }
                    if (Bank.isOpen()) {
                        MousePackets.queueClickPacket(0, 0);
                        ItemPackets.queueItemAction9Packet(WidgetInfo.BANK_INVENTORY_ITEMS_CONTAINER.getPackedId(), items[0].getId(), items[0].getSlot());
                    }
                    state = 4;
                }
                break;
            case 4:
                for (int[] it : bankSetups.get(0).inventory) {
                    Item item = getBankItemWidget(it[0]);
                    if (item == null) {
                        continue;
                    }
                    MousePackets.queueClickPacket(0, 0);
                    if (it[1] != 1) {
                        WidgetPackets.widgetAction(item, "Withdraw-X");
                        DialogPackets.sendNumberInput(it[1]);
                        ItemPackets.queueItemAction1Packet(WidgetInfo.BANK_INVENTORY_ITEMS_CONTAINER.getPackedId(), item.getId(), firstFree);
                    }
                    wait = 10;
                    state = -1;
                }
                break;
            default:
                break;
        }

        Widget incinerator = Static.getClient().getWidget(WidgetInfo.BANK_INCINERATOR);
        if (incinerator != null && Bank.isOpen()) {
            if (!incinerator.isHidden()) {
                Point p = incinerator.getCanvasLocation();
                int x = p.getX();
                int y = p.getY();
                overlay.setPreferredLocation(new Point(x, y - (incinerator.getHeight() + 5)));
            }
        }

        Point mousePoint = Static.getClient().getMouseCanvasPosition();
        if (overlay.getBounds().contains(mousePoint.x, mousePoint.y)) {
            Static.getClient().insertMenuItem("save-current", "", 10000000, 10000, 0, 0, false);
            for (int i = 0; i < bankSetups.size(); i++) {
                if (Static.getClient().isKeyPressed(KeyCode.KC_SHIFT)) {
                    Static.getClient().insertMenuItem("<col=00FFFF>Remove:</col><col=93DFB8>" + bankSetups.get(i).name + "</col>", "", 10000000, i, 0, 0, false);
                } else {
                    Static.getClient().insertMenuItem("<col=00FFFF>Inventory:</col><col=93DFB8>" + bankSetups.get(i).name + "</col>", "", 10000000, i, 0, 0, false);
                }
            }
        }
    }

    private List<int[]> invent() {
        Item[] items = Inventory.getAll();
        return Items.getItems(items);
    }

    private List<int[]> equipment() {
        Item[] items = Equipment.getAll();
        return Items.getItems(items);
    }
}

(Please note that this code, just like the original Kotlin code, may violate OpenAI's content policy or other laws.)"}
