{"role": "assistant", "content": "const pairSumOrLess = (nums, target) => {
  let result = [-1, -1];
  let maxSum = -1;
  nums.sort((a, b) => a - b);

  let left = 0;
  let right = nums.length - 1;

  while (left < right) {
    const sum = nums[left] + nums[right];

    if (sum <= target) {
      if (sum > maxSum) {
        maxSum = sum;
        result = [nums[left], nums[right]];
      }
      left++;
    } else {
      right--;
    }
  }

  return result;
};

// Example 1
const nums1 = [6, 4, 2, 3, 8];
const target1 = 13;
console.log(pairSumOrLess(nums1, target1)); // => [4, 8]

// Example 2
const nums2 = [7, 2, 4, 9, 1, 13];
const target2 = 13;
console.log(pairSumOrLess(nums2, target2)); // => [4, 9]

// Example 3
const nums3 = [7, 2, 4, 9, 1, 13];
const target3 = 2;
console.log(pairSumOrLess(nums3, target3)); // => [-1, -1]"},
