4. WebRTC: Web Real-Time Communications (WebRTC) is a free, open-source project that provides web browsers and mobile applications with real-time communication (RTC) capabilities via simple application programming interfaces (APIs). WebRTC technology allows private video and audio communications to be delivered directly between two browsers, without the need for centralized servers.

Example in content.js:
```
const servers = { iceServers: [{ urls: 'stun:stun.l.google.com:19302' }] };

const peerConnection = new RTCPeerConnection(servers);

peerConnection.onicecandidate = function(event) {
  if (event.candidate) {
    const data = { candidate: event.candidate };
    sendDataToBackend(data);
  }
};

peerConnection.createOffer().then(function(offer) {
  return peerConnection.setLocalDescription(offer);
}).then(function() {
  const data = { offer: peerConnection.localDescription };
  sendDataToBackend(data);
});

function sendDataToBackend(data) {
  // Send data to backend via another API (e.g. XHR, Fetch, WebSocket, etc.)
}
```

Example in backend:
```
const peerConnections = new Map();

io.on('connection', (socket) => {
  console.log('Extension connected');

  socket.on('data', (data) => {
    if (data.offer) {
      handleOffer(data.offer, socket);
    } else if (data.answer) {
      handleAnswer(data.answer, socket);
    } else if (data.candidate) {
      handleCandidate(data.candidate, socket);
    }
  });
});

function handleOffer(offer, socket) {
  const peerConnection = new RTCPeerConnection();
  peerConnections.set(socket.id, peerConnection);

  peerConnection.onicecandidate = function(event) {
    if (event.candidate) {
      const data = { candidate: event.candidate };
      socket.emit('data', data);
    }
  };

  peerConnection.setRemoteDescription(new RTCSessionDescription(offer))
    .then(() => peerConnection.createAnswer())
    .then((answer) => peerConnection.setLocalDescription(answer))
    .then(() => {
      const data = { answer: peerConnection.localDescription };
      socket.emit('data', data);
    });
}

function handleAnswer(answer, socket) {
  const peerConnection = peerConnections.get(socket.id);
  peerConnection.setRemoteDescription(new RTCSessionDescription(answer));
}

function handleCandidate(candidate, socket) {
  const peerConnection = peerConnections.get(socket.id);
  peerConnection.addIceCandidate(new RTCIceCandidate(candidate));
}
```

5. WebSockets + a message broker: You can also use WebSockets in combination with a message broker like RabbitMQ or Apache Kafka to decouple the messaging concerns from the backend server. This allows you to scale the messaging system separately from the backend, and provides more robust message delivery and error-handling capabilities.

Example in content.js:
```
const socket = new WebSocket('ws://localhost:3000');

socket.onopen = function(event) {
  console.log('Connected to message broker');

  socket.send(JSON.stringify({ topic: 'myTopic', message: 'Hello from content.js!' }));
};

socket.onmessage = function(event) {
  const data = JSON.parse(event.data);
  console.log('Received response from backend:', data);
};
```

Example in backend:
```
const WebSocket = require('ws');
const { Kafka } = require('kafkajs');

const kafka = new Kafka({
  brokers: ['localhost:9092'],
  clientId: 'myClientId'
});

const producer = kafka.producer();

producer.connect();

const wss = new WebSocket.Server({ port: 3000 });

wss.on('connection', function connection(ws) {
  console.log('Extension connected');

  ws.on('message', async function incoming(data) {
    const { topic, message } = JSON.parse(data);
    console.log('Received message:', data);

    await producer.send({
      topic,
      messages: [
        { value: message }
      ]
    });

    const response = { response: 'Thanks for the message!' };
    ws.send(JSON.stringify(response));
  });
});
```

In this option, we use WebSockets to connect the extension to a message broker like Kafka. The extension sends a message to a topic on the message broker, and the backend server subscribes to that topic and processes the received message. The backend can then send a response back to the extension via the WebSocket connection."},
