    <script src="https://cdnjs.cloudflare.com/ajax/libs/jquery/3.4.1/jquery.min.js"></script>
</head>
<body>
    <h1>Country Information</h1>
    <label for="country-select">Select a country:</label>
    <select id="country-select">
        <!-- Populate options with countries.json data -->
    </select>
    <br>
    <br>
    <div id="country-details" style="display: none;">
        <p id="country-name"></p>
        <img id="country-flag" src="" alt="Country Flag" width="200">
        <p id="country-population"></p>
        <label for="area-unit-select">Total Area in:</label>
        <select id="area-unit-select">
            <option value="sqmi">Square Miles</option>
            <option value="sqkm">Square Kilometers</option>
        </select>
        <p id="population-density"></p>
        <p id="world-population-percentage"></p>
        <button id="wiki-country" onclick="window.open('', '_blank')">Wiki Country</button>
        <br>
        <button id="flag-quiz">Launch Flag Quiz</button>
    </div>

    <script>
        // Fetch country data (use fetch and async-await to work with the real data)
        var countriesData = '{"countries": [{"name": "Country1", "flag": "flag1.jpg", "population": 1000000, "area_sqmi": 1000, "world_population_percentage": 0.1}, {"name": "Country2", "flag": "flag2.jpg", "population": 2000000, "area_sqmi": 2000, "world_population_percentage": 0.2}]}';

        $(document).ready(function() {
            var data = JSON.parse(countriesData);

            // Populate country-select options
            $.each(data.countries, function(index, country) {
                $('#country-select').append('<option value="' + index + '">' + country.name + '</option>');
            });

            // Country select change event
            $('#country-select').on('change', function() {
                updateCountryInformation(this.value);
                $('#country-details').show();
            });

            // Area unit select change event
            $('#area-unit-select').on('change', function() {
                updateAreaAndPopulationDensity();
            });

            // Launch Flag Quiz
            $('#flag-quiz').on('click', function() {
                window.open('flag-quiz.html', '_blank');
            });

            // Function to update country information
            function updateCountryInformation(index) {
                var selectedCountry = data.countries[index];
                $('#country-name').text(selectedCountry.name);
                $('#country-flag').attr('src', selectedCountry.flag);
                $('#country-population').text('Population: ' + selectedCountry.population.toLocaleString());
                $('#world-population-percentage').text('World Population Percentage: ' + selectedCountry.world_population_percentage.toFixed(2) + '%');
                updateAreaAndPopulationDensity();
                $('#wiki-country').attr('onclick', "window.open('https://en.wikipedia.org/wiki/" + selectedCountry.name.replace(' ', '_') + "', '_blank')");
            }

            // Function to update area and population density based on area unit
            function updateAreaAndPopulationDensity() {
                var selectedCountry = data.countries[$('#country-select').val()];
                var areaUnit = $('#area-unit-select').val();
                var area = areaUnit === 'sqmi' ? selectedCountry.area_sqmi : selectedCountry.area_sqmi * 2.58999;
                var unitText = areaUnit === 'sqmi' ? 'Square Miles' : 'Square Kilometers';
                var populationDensity = selectedCountry.population / area;
                $('#population-density').text('Population Density per ' + unitText + ': ' + populationDensity.toFixed(2));
            }
        });
    </script>
</body>
</html>

