            }
            System.out.println();
            System.out.println("-------------");
        }
    }

    // Method to get the input from the player
    public static void getInput() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter row number (1-3): ");
        int row = in.nextInt();
        System.out.print("Enter column number (1-3): ");
        int col = in.nextInt();
        if (board[row-1][col-1] == ' ') {
            board[row-1][col-1] = currentPlayer;
        } else {
            System.out.println("Invalid move, try again.");
            getInput();
        }
    }

    // Method to check if the game is over
    public static boolean isGameOver() {
        if (hasWon('X') || hasWon('O') || isTie()) {
            return true;
        }
        return false;
    }

    // Method to check if the game is won
    public static boolean hasWon(char player) {
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    // Method to check if the game is tied
    public static boolean isTie() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == ' ') {
                    return false;
                }
            }
        }
        return true;
    }

    // Method to switch between players
    public static void switchPlayer() {
        if (currentPlayer == 'X') {
            currentPlayer = 'O';
        } else {
            currentPlayer = 'X';
        }
    }

    public static void main(String[] args) {
        initBoard();
        printBoard();
        while (!isGameOver) {
            System.out.println("Player " + currentPlayer + " turn:");
            getInput();
            printBoard();
            if (isGameOver()) {
                System.out.println("Game over!");
                if (hasWon(currentPlayer)) {
                    System.out.println("Player " + currentPlayer + " has won!");
                } else {
                    System.out.println("It's a tie!");
                }
                isGameOver = true;
            } else {
                switchPlayer();
            }
        }
    }
}

