public class BillCalculator {

  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    // Prompt the user for the number of people sharing the bill
    System.out.print("How many people are sharing the bill? ");
    int numPeople = scanner.nextInt();

    // Initialize an ArrayList to hold the items
    ArrayList<Item> items = new ArrayList<>();

    // Prompt the user for the items and their respective costs
    while (true) {
      scanner.nextLine();

      System.out.print("Enter the name of the item (or 'done' to finish adding items): ");
      String itemName = scanner.nextLine();

      if (itemName.equals("done")) {
        break;
      }

      System.out.print("Enter the cost of the item: ");
      double itemCost = scanner.nextDouble();

      items.add(new Item(itemName, itemCost));
    }

    // Calculate the total cost and cost per person
    double totalCost = 0;
    for (Item item : items) {
      totalCost += item.getCost();
    }
    double costPerPerson = totalCost / numPeople;

    // Print the bill
    System.out.println("+--------------------------------------------------------+");
    System.out.printf("| %1$-40s | %2$10s |\n", "ITEM", "COST");
    System.out.println("+--------------------------------------------------------+");
    for (Item item : items) {
      System.out.printf("| %1$-40s | %2$10.2f |\n", item.getName(), item.getCost());
    }
    System.out.println("+--------------------------------------------------------+");
    System.out.printf("| %1$-40s | %2$10.2f |\n", "TOTAL COST", totalCost);
    System.out.printf("| %1$-40s | %2$10.2f |\n", "COST PER PERSON", costPerPerson);
    System.out.println("+--------------------------------------------------------+");
  }
}

class Item {
  private String name;
  private double cost;

