import com.patrykandpatrick.vico.Compose.chart.builders.entriesOf
import com.patrykandpatrick.vico.Compose.chart.builders.startAxis

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MaterialTheme {
                Surface(color = MaterialTheme.colors.surface) {
                    Column {
                        var selectedTimePeriod by remember { mutableStateOf(TimePeriod.Daily) }
                        TimePeriodSelector(
                            selectedTimePeriod = selectedTimePeriod,
                            onTimePeriodChanged = { newTimePeriod -> selectedTimePeriod = newTimePeriod }
                        )
                        // Pass your daily expenses data here
                        val dailyExpenses = listOf(4f, 12f, 8f, 16f)
                        ExpensesChart(selectedTimePeriod = selectedTimePeriod, dailyExpenses = dailyExpenses)
                    }
                }
            }
        }
    }
}

@Composable
fun TimePeriodSelector(
    selectedTimePeriod: TimePeriod,
    onTimePeriodChanged: (TimePeriod) -> Unit
) {
    OutlinedButtonGroup(
        modifier = Modifier.fillMaxWidth(),
        selected = selectedTimePeriod.ordinal,
        onSelectedChange = { index -> onTimePeriodChanged(TimePeriod.values()[index]) },
        items = TimePeriod.values().toList(),
        itemContent = { timePeriod -> Text(timePeriod.name) }
    )
}

enum class TimePeriod {
    Daily,
    Weekly,
    Monthly,
    Yearly
}

@Composable
fun ExpensesChart(selectedTimePeriod: TimePeriod, dailyExpenses: List<Float>) {
    val expensesData = when (selectedTimePeriod) {
        TimePeriod.Daily -> dailyExpenses
        TimePeriod.Weekly -> calculateWeeklyExpenses(dailyExpenses) // Implement this based on your data
        TimePeriod.Monthly -> calculateMonthlyExpenses(dailyExpenses) // Implement this based on your data
        TimePeriod.Yearly -> calculateYearlyExpenses(dailyExpenses) // Implement this based on your data
    }

    val chartEntryModelProducer = ChartEntryModelProducer(entriesOf(*expensesData.toFloatArray()))

    Chart(
        chart = columnChart(),
        chartModelProducer = chartEntryModelProducer,
        startAxis = startAxis(),
        bottomAxis = bottomAxis(),
    )
}

// Implement these functions based on how you want to calculate the weekly, monthly, and yearly expenses
fun calculateWeeklyExpenses(dailyExpenses: List<Float>): List<Float> {
    // Example implementation
    return dailyExpenses.chunked(7).map { week -> week.sum() }
}

fun calculateMonthlyExpenses(dailyExpenses: List<Float>): List<Float> {
    // Example implementation
    return dailyExpenses.chunked(30).map { month -> month.sum() }
}

fun calculateYearlyExpenses(dailyExpenses: List<Float>): List<Float> {
    // Example implementation
    return dailyExpenses.chunked(365).map { year -> year.sum() }
}
```
